PROMPT_BASIC = 'import Mathlib\n\nnamespace TuringTask\n\nnoncomputable def ex (x : Real) : Complex :=\n  Complex.exp (2 * (Real.pi : Complex) * Complex.I * (x : Complex))\n\nnoncomputable def rt (n : Nat) : Complex :=\n  if n % 4 = 1 then ((Real.sqrt (n : Real) : Real) : Complex)\n  else Complex.I * ((Real.sqrt (n : Real) : Real) : Complex)\n\ntheorem sum_sq (n : Nat) (hn : n % 2 = 1) :\n    Finset.sum (Finset.range n) (fun k : Nat => ex ((k : Real) ^ 2 / (n : Real))) = rt n := by\n  sorry\n\ntheorem sum_tri (n : Nat) (hn : n % 2 = 1) :\n    Finset.sum (Finset.range n) (fun k : Nat =>\n        ex ((k : Real) * ((k : Real) + 1) / (2 * (n : Real)))) =\n      ex (((n : Real) - 1) / (8 * (n : Real))) * ((Real.sqrt (n : Real) : Real) : Complex) := by\n  sorry\n\ntheorem sum_legendre (p : Nat) [Fact p.Prime] (hp : p % 2 = 1) (a : Int) :\n    Finset.sum (Finset.range p) (fun k : Nat =>\n        ((legendreSym p (k : Int) : Int) : Complex) *\n          ex ((a : Real) * (k : Real) / (p : Real))) =\n      ((legendreSym p a : Int) : Complex) * rt p := by\n  sorry\n\ntheorem sum_sq_mul (p q : Nat) [Fact p.Prime] [Fact q.Prime]\n    (hp : p % 2 = 1) (hq : q % 2 = 1) (hpq : Not (p = q)) :\n    Finset.sum (Finset.range p) (fun j : Nat =>\n        ex ((q : Real) * (j : Real) ^ 2 / (p : Real))) *\n      Finset.sum (Finset.range q) (fun k : Nat =>\n        ex ((p : Real) * (k : Real) ^ 2 / (q : Real))) = rt (p * q) := by\n  sorry\n\ntheorem sum_cot (p : Nat) [Fact p.Prime] (hp : p % 4 = 3) :\n    Real.sqrt (p : Real) * Finset.sum (Finset.range p) (fun k : Nat =>\n        ((legendreSym p (k : Int) : Int) : Real) *\n          Real.cot (Real.pi * (k : Real) / (p : Real))) =\n      -2 * Finset.sum (Finset.range p) (fun k : Nat =>\n        (k : Real) * ((legendreSym p (k : Int) : Int) : Real)) := by\n  sorry\n\nend TuringTask\n'


def check():
    for name, text in FILES.items():
        assert hashlib.sha256(text.encode("utf-8")).hexdigest() == SHA256[name], name
    for name, text in TEXTS.items():
        bad = sorted({ch for ch in text if ord(ch) > 127 or (ord(ch) < 32 and ch != "\n")})
        assert not bad, (name, bad)
    for name in ("README.md", "lakefile.toml", "StatementAndAxiomsCheck.lean",
                 "TuringTask/Basic.lean"):
        assert all(ord(ch) < 128 for ch in FILES[name]), name
    assert 'path = "/opt/mathlib4"' in FILES["lakefile.toml"]
    assert "git =" not in FILES["lakefile.toml"]
    assert '"dir": "/opt/mathlib4"' in FILES["lake-manifest.json"]
    basic = FILES["TuringTask/Basic.lean"]
    pre = PROMPT_BASIC[PROMPT_BASIC.index("noncomputable def ex"):
                       PROMPT_BASIC.index("theorem sum_sq")]
    assert pre in basic
    for m in re.finditer(r"theorem \w+ .*? := by\n", PROMPT_BASIC, re.S):
        assert m.group(0) in basic, m.group(0)[:40]
    assert basic.startswith("import Mathlib\n") and "namespace TuringTask" in basic
    joined = "\n".join(v for k, v in FILES.items() if k.endswith(".lean") and "Check" not in k)
    for word in ("sorry", "admit", "native_decide", "axiom", "set_option", "instance", "unsafe"):
        assert not re.search(r"(?<![A-Za-z_.])" + word + r"\b", joined), word
    rows = TEXTS["task6_rubric.csv"].split("\n")
    assert rows[0] == '"ID","Criterion","Weight"' and len(rows) == 9
    assert not TEXTS["task6_rubric.csv"].endswith("\n")
    for i, row in enumerate(rows[1:], 1):
        assert row.startswith(f'"{i}","') and row.endswith('","1"') and row.count('"') == 6
    banned = ("proves", "derives", "works out", "figures out", "computes", "understood",
              "considered", "recognized", "accounted", "clean", "idiomatic", "elegant", "clear",
              "appropriate", "thorough", "correctly", "robust")
    crit = TEXTS["task6_rubric.txt"].lower()
    for word in banned:
        assert not re.search(r"\b" + word + r"\b", crit), word
    assert len(re.findall(r"\bsound\b", crit)) == 5      # only inside the axiom name Quot.sound


def main():
    check()
    here = Path(__file__).resolve().parent
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for name in FILES:
            info = zipfile.ZipInfo(f"{PROJECT}/{name}", date_time=(2026, 10, 8, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o644 << 16
            z.writestr(info, FILES[name].encode("utf-8"))
    (here / "golden_solution.zip").write_bytes(buf.getvalue())
    print("wrote golden_solution.zip", len(buf.getvalue()), "bytes, sha256",
          hashlib.sha256(buf.getvalue()).hexdigest()[:16])
    for name, text in TEXTS.items():
        with open(here / name, "w", encoding="ascii", newline="\n") as fh:
            fh.write(text)
        print("wrote", name, len(text), "chars, ASCII ok")
    lean = [n for n in FILES if n.startswith("TuringTask/")]
    print("Lean lines:", {n: FILES[n].count("\n") for n in lean},
          "total", sum(FILES[n].count("\n") for n in lean))


if __name__ == "__main__":
    main()
